={
  "input": {
    "bounds": {
      "properties": {
        "crs": "http://www.opengis.net/def/crs/OGC/1.3/CRS84"
      },
      "bbox": [
        {{ $json.bbox }}
      ]
    },
    "data": [
      {
        "type": "sentinel-2-l2a",
        "dataFilter": {
          "timeRange": {
            "from": "2025-05-20T00:00:00Z",
            "to": "2025-05-26T23:59:59Z"
          },
          "maxCloudCoverage": 50,
          "mosaicOrder": "leastCC"
        }
      }
    ]
  },
  "output": {
    "width": 512,
    "height": 512,
    "responses": [
      {
        "identifier": "default",
        "format": {
          "type": "image/tiff"
        }
      }
    ]
  },
  "evalscript": "//VERSION=3\nfunction setup() {\n  return {\n    input: [\"B04\", \"B08\"],\n    output: { bands: 3 }\n  };\n}\nfunction evaluatePixel(sample) {\n  let ndvi = (sample.B08 - sample.B04) / (sample.B08 + sample.B04);\n  if (ndvi < 0.1) return [1, 0, 0]; // red = bad for solar\n  else if (ndvi < 0.3) return [1, 1, 0]; // yellow = moderate\n  else return [0, 1, 0]; // green = good solar potential\n}"
}

