const sensorMap = {
  9255955: "pm1",
  9255937: "pm10",
  9255953: "pm25",
  9255958: "humidity",
  9255938: "temperature",
  9255960: "pm0.3"
};

const rawResults = $json.results;
const output = rawResults.map(item => {
  const id = item.sensorsId;
  return {
    json: {
      sensorId: id,
      parameter: sensorMap[id] || `sensor_${id}`,
      value: item.value,
      timestamp: item.datetime.utc,
      locationId: item.locationsId,
      coordinates: item.coordinates
    }
  };
});

return output;

const data3h = $json["data_3h"];
const metadata = $json["metadata"];
const index = 0;

// Extract all relevant variables first
const pm10 = data3h.pm10[index];
const pm25 = data3h.pm25[index];
const airqualityindex = data3h.airqualityindex[index];
const humidity = data3h.relativehumidity[index];
const precipitation = data3h.precipitation[index];
const soil_moisture = data3h.soilmoisture_0to10cm[index];

// Build full output object
const output = {
  timestamp: new Date().toISOString(),

  // General Weather & Location
  temperature: data3h.temperature[index],
  humidity,
  windspeed: data3h.windspeed[index],
  winddirection: data3h.winddirection[index],
  airqualityindex,
  location: {
    latitude: metadata.latitude,
    longitude: metadata.longitude,
    timezone: metadata.timezone_abbrevation
  },

  // Air Pollution
  pm10,
  pm25,
  ozone: data3h.ozone[index],
  no2: data3h.no2[index],
  co: data3h.co[index],
  so2: data3h.so2[index],
  dust_concentration: data3h.dust_concentration[index],
  aod550: data3h.aod550[index],

  // Water & Soil
  precipitation,
  precipitation_probability: data3h.precipitation_probability[index],
  soil_moisture,
  evapotranspiration: data3h.evapotranspiration[index],
  reference_et0: data3h.referenceevapotranspiration_fao[index],

  // Solar & Energy
  ghi: data3h.ghi_total[index],
  dni: data3h.dni_total[index],
  wind_gust: data3h.gust[index],
  air_density: data3h.airdensity[index],

  // 🚨 Smart Alert
  alert: (
    pm10 > 50 ||
    pm25 > 25 ||
    (airqualityindex > 75 && humidity < 30) || // health alert
    (precipitation > 10 && soil_moisture > 80) // overflow risk
  )
};

return [{ json: output }];

const metersToDegrees = meters => meters / 111320;
const buffer = metersToDegrees(200); // 100m = 50m radius

return items.map(item => {
  const lat = item.json.latitude;
  const lon = item.json.longitude;

  return {
    json: {
      ...item.json,
      bbox: [
        lon - buffer,
        lat - buffer,
        lon + buffer,
        lat + buffer
      ]
    }
  };
});

const zoom = 18; // Change zoom level here

function latLonToTile(lat, lon, zoom) {
  const x = Math.floor((lon + 180) / 360 * Math.pow(2, zoom));
  const y = Math.floor(
    (1 - Math.log(Math.tan(lat * Math.PI / 180) + 1 / Math.cos(lat * Math.PI / 180)) / Math.PI) / 2 * Math.pow(2, zoom)
  );
  return { x, y, z: zoom };
}

return $input.all().map(item => {
  const lat = item.json.latitude;
  const lon = item.json.longitude;
  const tile = latLonToTile(lat, lon, zoom);

  return {
    json: {
      ...item.json,
      tileX: tile.x,
      tileY: tile.y,
      tileZ: tile.z
    }
  };
});

const z = $json["tileZ"];
const x = $json["tileX"];
const y = $json["tileY"];
const session = $json["session"];
const key = $json["GOOGLE_MAPS_API_KEY"];

const tile_url = `https://tile.googleapis.com/v1/2dtiles/${z}/${x}/${y}?session=${session}&key=${key}`;

return {
  id: $json["id"],
  tile_url
};

