={
  "input": {
    "bounds": {
      "bbox": [
        {{ $json.bbox.minLon }},
        {{ $json.bbox.minLat }},
        {{ $json.bbox.maxLon }},
        {{ $json.bbox.maxLat }}
      ],
      "properties": {
        "crs": "http://www.opengis.net/def/crs/OGC/1.3/CRS84"
      }
    },
    "data": [
      {
        "type": "sentinel-2-l2a",
        "dataFilter": {
          "timeRange": {
            "from": "2025-05-20T00:00:00Z",
            "to": "2025-05-26T23:59:59Z"
          }
        }
      }
    ]
  },
  "output": {
    "width": {{ 
      (() => {
        const maxPixels = 2048;
        const minLon = $json.bbox.minLon;
        const maxLon = $json.bbox.maxLon;
        const minLat = $json.bbox.minLat;
        const maxLat = $json.bbox.maxLat;

        const bboxWidth = maxLon - minLon;
        const bboxHeight = maxLat - minLat;

        if (bboxWidth > bboxHeight) {
          return maxPixels;
        } else {
          return Math.round(maxPixels * (bboxWidth / bboxHeight));
        }
      })()
    }},
    "height": {{ 
      (() => {
        const maxPixels = 2048;
        const minLon = $json.bbox.minLon;
        const maxLon = $json.bbox.maxLon;
        const minLat = $json.bbox.minLat;
        const maxLat = $json.bbox.maxLat;

        const bboxWidth = maxLon - minLon;
        const bboxHeight = maxLat - minLat;

        if (bboxHeight >= bboxWidth) {
          return maxPixels;
        } else {
          return Math.round(maxPixels * (bboxHeight / bboxWidth));
        }
      })()
    }},
    "responses": [
      {
        "identifier": "default",
        "format": {
          "type": "image/jpeg"
        }
      }
    ]
  },
"evalscript": "//VERSION=3\nfunction setup() {\n  return {\n    input: [\"B03\", \"B08\", \"dataMask\"],\n    output: { bands: 3 }\n  };\n}\n\nconst ramp = [\n  [-0.8, 0x008000],\n  [0, 0xFFFFFF],\n  [0.8, 0x0000CC]\n];\n\nlet viz = new ColorRampVisualizer(ramp);\n\nfunction evaluatePixel(samples) {\n  const val = index(samples.B03, samples.B08);\n  let imgVals = viz.process(val);\n  return imgVals.concat([samples.dataMask]);\n}"

}

